#include "rinkfit/augmented_lagrangian.hpp"
#include "rinkfit/state_text_codec.hpp"
#include <ostream>
namespace rinkfit { namespace {
using state_text::Writer;using state_text::Reader;using state_text::require;
void write_vector(Writer&out,const std::vector<double>&v){out.integer(v.size());for(double x:v){out.ch(' ');out.number(x);}out.ch('\n');}
std::vector<double> read_vector(Reader&in){auto n=in.count();std::vector<double>v;v.reserve(n);for(std::size_t i=0;i<n;++i)v.push_back(in.number());return v;}
void write_map(Writer&out,const std::map<std::string,std::string>&m){out.integer(m.size());out.ch('\n');for(const auto&v:m){out.quoted(v.first);out.ch(' ');out.quoted(v.second);out.ch('\n');}}
std::map<std::string,std::string>read_map(Reader&in){std::map<std::string,std::string>m;auto n=in.count();for(std::size_t i=0;i<n;++i){auto k=in.quoted();auto v=in.quoted();require(m.emplace(std::move(k),std::move(v)).second,"duplicate checkpoint discrete key");}return m;}
void write_state(Writer&out,const StateSnapshot&s){out.integer(int(!s.empty()));out.ch('\n');if(s.empty())return;const auto&d=s.data();const auto&id=d.identity;out.quoted(s.token());out.ch('\n');const std::string*ids[]={&id.source_id,&id.model_id,&id.budget_id,&id.statistics_id,&id.scales_id,&id.objective_id};for(int i=0;i<6;++i){out.quoted(*ids[i]);out.ch(i==5?'\n':' ');}out.integer(d.parameters.size());out.ch('\n');for(const auto&p:d.parameters){out.quoted(p.name);out.ch(' ');out.integer(int(p.equality_auxiliary));out.ch('\n');write_vector(out,p.values);}write_map(out,d.discrete);write_map(out,d.root_charts);}
StateSnapshot read_state(Reader&in){auto present=in.count();require(present<=1,"invalid checkpoint snapshot flag");if(!present)return {};auto token=in.quoted();StatePayload d;auto&id=d.identity;id.source_id=in.quoted();id.model_id=in.quoted();id.budget_id=in.quoted();id.statistics_id=in.quoted();id.scales_id=in.quoted();id.objective_id=in.quoted();auto n=in.count();d.parameters.reserve(n);std::size_t total=0;for(std::size_t i=0;i<n;++i){ParameterValues p;p.name=in.quoted();auto flag=in.count();require(flag<=1,"invalid auxiliary flag");p.equality_auxiliary=flag==1;p.values=read_vector(in);total+=p.values.size();require(total<=20000000,"checkpoint total parameter size exceeds parser limit");d.parameters.push_back(std::move(p));}d.discrete=read_map(in);d.root_charts=read_map(in);StateSnapshot s(std::move(d));require(s.token()==token,"checkpoint snapshot token mismatch: corrupted or edited complete state");return s;}
}
void write_checkpoint(std::ostream&stream,const RunCheckpoint&c){require(!c.state.empty(),"cannot save an empty current state");Writer out;out.text.reserve(c.state.data().parameters.size()*64);out.raw("RINKFIT_AL_CHECKPOINT_V1\n");out.quoted(c.runtime_fingerprint);out.ch('\n');const auto&a=c.outer;out.integer(int(a.phase));out.ch(' ');out.integer(a.outer_iteration);out.ch(' ');out.integer(a.inner_attempt);out.ch(' ');out.integer(a.chart_restarts);out.ch(' ');out.number(a.rho);out.ch(' ');out.number(a.previous_progress);out.ch(' ');out.number(a.elapsed_seconds);out.ch('\n');write_vector(out,a.lambda);write_vector(out,a.nu);write_state(out,c.state);write_state(out,c.best_physical_state);out.raw("END_RINKFIT_AL_CHECKPOINT\n");stream.write(out.text.data(),std::streamsize(out.text.size()));require(bool(stream),"checkpoint write failed");}
RunCheckpoint read_checkpoint(std::istream&stream){Reader in(stream);require(in.token()=="RINKFIT_AL_CHECKPOINT_V1","unsupported checkpoint format");RunCheckpoint c;c.runtime_fingerprint=in.quoted();auto phase=in.count();require(phase==1||phase==2,"invalid saved phase");auto&a=c.outer;a.phase=static_cast<Phase>(phase);a.outer_iteration=in.count();a.inner_attempt=in.count();a.chart_restarts=in.count();a.rho=in.number();a.previous_progress=in.number();a.elapsed_seconds=in.number();a.lambda=read_vector(in);a.nu=read_vector(in);c.state=read_state(in);c.best_physical_state=read_state(in);require(in.token()=="END_RINKFIT_AL_CHECKPOINT","truncated checkpoint");require(!c.state.empty(),"checkpoint has no current state");return c;}
}
